// Étape 1 : laisser 'single' pour l'essai isolé. Étapes suivantes : choisir 'batch'.
const benchmarkMode = 'single';
const batchSize = 10; // entier de 1 à 10 en mode 'batch'

// Pour reprendre un autre jour, remplacer cet objet par le contenu du dernier
// fichier gemini-benchmark-checkpoint-XX.json téléchargé depuis ce workflow.
const checkpoint = {
  version: 1,
  dataset_id: 'seed-demo-v1',
  model: 'models/gemini-3.5-flash',
  results: [],
  groups: [],
};

if (!['single', 'batch'].includes(benchmarkMode)) throw new Error('Mode benchmark invalide.');
if (!Number.isInteger(batchSize) || batchSize < 1 || batchSize > 10) throw new Error('batchSize doit être compris entre 1 et 10.');
if (checkpoint.version !== 1 || checkpoint.dataset_id !== 'seed-demo-v1') throw new Error('Checkpoint incompatible.');
if (checkpoint.model !== 'models/gemini-3.5-flash') throw new Error('Le modèle du checkpoint ne correspond pas.');
if (!Array.isArray(checkpoint.results) || !Array.isArray(checkpoint.groups)) throw new Error('Checkpoint incomplet.');
if (checkpoint.results.length > 30) throw new Error('Checkpoint supérieur à 30 résultats.');
const ids = checkpoint.results.map((result) => result.fixture_id);
if (ids.some((id) => typeof id !== 'string') || new Set(ids).size !== ids.length) throw new Error('Checkpoint avec identifiants invalides ou dupliqués.');

const messageLimit = benchmarkMode === 'single' ? 1 : batchSize;
return [{ json: {
  benchmark_mode: benchmarkMode,
  message_limit: messageLimit,
  dataset_size: 30,
  pause_seconds: 5,
  logical_call_limit: messageLimit * 2,
  transport_attempt_limit: messageLimit * 4,
  benchmark_started_ms: Date.now(),
  checkpoint_results: benchmarkMode === 'batch' ? checkpoint.results : [],
  checkpoint_groups: benchmarkMode === 'batch' ? checkpoint.groups : [],
} }];

const config = $json;
const threads = [{"subject": "Renouvellement du contrat de maintenance", "category": "client", "priority": 3, "senders": ["claire@atelier-lumiere.fr", "juridique@atelier-lumiere.fr"], "bodies": ["Bonjour, notre contrat arrive à échéance. Pouvez-vous nous envoyer une proposition actualisée ?", "Merci pour votre retour. Nous souhaitons conserver le même périmètre avec une assistance prioritaire.", "Notre service juridique a ajouté deux remarques sur les délais d’intervention.", "La direction valide le budget proposé. Pouvez-vous préparer la version à signer ?", "Le contrat signé est joint à ce message. Merci de confirmer sa bonne réception."]}, {"subject": "Facture hébergement – septembre", "category": "facture", "priority": 2, "senders": ["facturation@cloudhexagone.fr", "compta@cloudhexagone.fr"], "bodies": ["Bonjour, vous trouverez votre facture mensuelle d’hébergement en pièce jointe.", "Nous constatons que le règlement n’apparaît pas encore sur votre compte client.", "Pouvez-vous nous transmettre la référence du virement afin de faire le rapprochement ?", "Le paiement a bien été identifié. Votre compte est maintenant à jour.", "Merci de conserver ce message comme confirmation de règlement."]}, {"subject": "Organisation de la démonstration produit", "category": "rendez-vous", "priority": 3, "senders": ["sophie.martin@novacorp.fr", "thomas@novacorp.fr"], "bodies": ["Bonjour, seriez-vous disponible mardi prochain pour une démonstration à notre équipe ?", "Le créneau de 10 h convient à six participants. La réunion peut se tenir en visioconférence.", "Pourriez-vous prévoir un exemple autour du suivi des demandes clients ?", "Voici le lien de connexion et la liste définitive des participants.", "Merci pour la démonstration. Nous aimerions planifier un atelier technique complémentaire."]}, {"subject": "La lettre numérique de la semaine", "category": "newsletter", "priority": 1, "senders": ["newsletter@frenchtech.example", "evenements@frenchtech.example"], "bodies": ["Cette semaine : financement, cybersécurité et nouveaux outils pour les équipes produit.", "Découvrez notre entretien avec trois entrepreneuses qui développent leur activité en Europe.", "Les inscriptions pour la rencontre mensuelle sont ouvertes jusqu’à vendredi.", "Notre sélection présente cinq ressources pratiques pour mieux mesurer la satisfaction client.", "Retrouvez les événements et appels à projets du mois prochain dans notre agenda."]}, {"subject": "Offre exceptionnelle réservée aux professionnels", "category": "spam probable", "priority": 1, "senders": ["promo@offres-express.example", "contact@gains-rapides.example"], "bodies": ["Profitez aujourd’hui seulement d’une remise exceptionnelle sur notre catalogue professionnel.", "Votre entreprise a été sélectionnée pour recevoir un avantage exclusif sans engagement.", "Cliquez sur notre lien pour confirmer vos coordonnées avant la fin de la journée.", "Il ne reste que quelques heures pour bénéficier de cette proposition commerciale.", "Dernier rappel : votre avantage expirera ce soir à minuit."]}, {"subject": "Mise à jour des accès au bureau", "category": "autre", "priority": 2, "senders": ["accueil@espace-republique.fr", "support@espace-republique.fr"], "bodies": ["Bonjour, le système de badges sera mis à jour ce week-end dans l’ensemble du bâtiment.", "Merci de vérifier votre numéro de badge dans votre espace locataire avant jeudi.", "Une permanence sera disponible vendredi matin pour remplacer les badges non reconnus.", "Les tests sont terminés et tous les accès principaux fonctionnent normalement.", "N’hésitez pas à contacter l’accueil si vous rencontrez encore une difficulté d’accès."]}];
const messages = [];
threads.forEach((thread, threadIndex) => {
  thread.bodies.forEach((body, messageIndex) => {
    const number = threadIndex * 5 + messageIndex + 1;
    messages.push({ json: {
      benchmark_mode: config.benchmark_mode,
      benchmark_started_ms: config.benchmark_started_ms,
      logical_call_limit: config.logical_call_limit,
      transport_attempt_limit: config.transport_attempt_limit,
      fixture_id: `demo-seed-v1-message-${String(threadIndex + 1).padStart(2, '0')}-${String(messageIndex + 1).padStart(2, '0')}`,
      subject: messageIndex === 0 ? thread.subject : `Re: ${thread.subject}`,
      body,
    } });
  });
});
if (messages.length !== 30) throw new Error(`Jeu seed_demo incohérent: ${messages.length} messages.`);
const completedIds = new Set((config.checkpoint_results ?? []).map((result) => result.fixture_id));
const remaining = messages.filter((item) => !completedIds.has(item.json.fixture_id));
if (config.benchmark_mode === 'batch' && remaining.length === 0) throw new Error('Les 30 messages ont déjà été évalués.');
return remaining.slice(0, config.message_limit).map((item) => ({ json: {
  ...item.json,
  benchmark_mode: config.benchmark_mode,
  checkpoint_results: config.checkpoint_results ?? [],
  checkpoint_groups: config.checkpoint_groups ?? [],
} }));

const allowedCategories = new Set(['client', 'facture', 'rendez-vous', 'newsletter', 'spam probable', 'autre']);
const requiredKeys = ['category', 'expected_action', 'priority', 'summary'];

function validate(raw) {
  try {
    if (typeof raw !== 'string') return null;
    const parsed = JSON.parse(raw.trim());
    if (!parsed || Array.isArray(parsed) || typeof parsed !== 'object') return null;
    const keys = Object.keys(parsed).sort();
    if (JSON.stringify(keys) !== JSON.stringify(requiredKeys)) return null;
    if (!allowedCategories.has(parsed.category)) return null;
    if (!Number.isInteger(parsed.priority) || parsed.priority < 1 || parsed.priority > 3) return null;
    if (typeof parsed.summary !== 'string' || !parsed.summary.trim() || parsed.summary.trim().length > 1000) return null;
    if (typeof parsed.expected_action !== 'string' || !parsed.expected_action.trim() || parsed.expected_action.trim().length > 2000) return null;
    return {
      category: parsed.category,
      priority: parsed.priority,
      summary: parsed.summary.trim(),
      expected_action: parsed.expected_action.trim(),
      needs_review: false,
    };
  } catch {
    return null;
  }
}

return $input.all().map((item) => {
  const classification = validate(item.json.text);
  return { json: { valid: classification !== null, classification, raw: item.json.text ?? '' } };
});

const input = $('Entrée classification').item.json;
const response = $('Classification Gemini').item.json;
const serializedError = JSON.stringify(response?.error ?? '');
const technicalError = Boolean(response?.error);
const http429 = technicalError && /(?:\b429\b|quota|resource.?exhausted|rate.?limit)/i.test(serializedError);
const http503 = technicalError && /(?:\b503\b|service.?unavailable|temporarily.?unavailable)/i.test(serializedError);
return [{ json: {
  ...input,
  raw: $json.raw ?? '',
  first_valid: $json.valid === true && !technicalError,
  first_classification: $json.classification ?? null,
  technical_error: technicalError,
  http_429_error: http429,
  http_503_error: http503,
  quota_error: http429 || http503,
  error_code: http429 ? 'http_429' : (http503 ? 'http_503' : (technicalError ? 'gemini_initial_error' : null)),
} }];

