const allowedCategories = new Set(['client', 'facture', 'rendez-vous', 'newsletter', 'spam probable', 'autre']);
const requiredKeys = ['category', 'expected_action', 'priority', 'summary'];

function validate(raw) {
  try {
    if (typeof raw !== 'string') return null;
    const parsed = JSON.parse(raw.trim());
    if (!parsed || Array.isArray(parsed) || typeof parsed !== 'object') return null;
    const keys = Object.keys(parsed).sort();
    if (JSON.stringify(keys) !== JSON.stringify(requiredKeys)) return null;
    if (!allowedCategories.has(parsed.category)) return null;
    if (!Number.isInteger(parsed.priority) || parsed.priority < 1 || parsed.priority > 3) return null;
    if (typeof parsed.summary !== 'string' || !parsed.summary.trim() || parsed.summary.trim().length > 1000) return null;
    if (typeof parsed.expected_action !== 'string' || !parsed.expected_action.trim() || parsed.expected_action.trim().length > 2000) return null;
    return {
      category: parsed.category,
      priority: parsed.priority,
      summary: parsed.summary.trim(),
      expected_action: parsed.expected_action.trim(),
      needs_review: false,
    };
  } catch {
    return null;
  }
}

return $input.all().map((item) => {
  const classification = validate(item.json.text);
  return { json: { valid: classification !== null, classification } };
});

const initial = $('Conserver métriques initiales').item.json;
const response = $('Nouvelle tentative Gemini').item.json;
const serializedError = JSON.stringify(response?.error ?? '');
const technicalError = Boolean(response?.error);
const http429 = technicalError && /(?:\b429\b|quota|resource.?exhausted|rate.?limit)/i.test(serializedError);
const http503 = technicalError && /(?:\b503\b|service.?unavailable|temporarily.?unavailable)/i.test(serializedError);
return [{ json: {
  ...initial,
  retry_valid: $json.valid === true && !technicalError,
  retry_technical_error: technicalError,
  retry_http_429_error: http429,
  retry_http_503_error: http503,
  retry_quota_error: http429 || http503,
  retry_error_code: http429 ? 'http_429' : (http503 ? 'http_503' : (technicalError ? 'gemini_retry_error' : null)),
} }];

const currentResults = $input.all().map((item) => item.json);
if (currentResults.length < 1 || currentResults.length > 10) throw new Error(`Taille de groupe interdite: ${currentResults.length}.`);
const first = currentResults[0];
const calibrationOnly = first.benchmark_mode === 'single';
const previousResults = calibrationOnly ? [] : (first.checkpoint_results ?? []);
const previousGroups = calibrationOnly ? [] : (first.checkpoint_groups ?? []);
const clean = (result) => {
  const { benchmark_started_ms, benchmark_mode, checkpoint_results, checkpoint_groups, ...safe } = result;
  return safe;
};
const newResults = currentResults.map(clean);
const results = calibrationOnly ? newResults : [...previousResults, ...newResults];
const fixtureIds = results.map((result) => result.fixture_id);
if (new Set(fixtureIds).size !== fixtureIds.length) throw new Error('Résultats dupliqués dans le checkpoint.');
if (results.length > 30) throw new Error(`Nombre total de résultats interdit: ${results.length}.`);
const groupDuration = Date.now() - first.benchmark_started_ms;
const groups = calibrationOnly ? [] : [...previousGroups, {
  group_number: previousGroups.length + 1,
  message_count: newResults.length,
  duration_ms: groupDuration,
  completed_at: new Date().toISOString(),
}];
const initialValid = results.filter((r) => r.first_attempt_valid).length;
const technicalErrors = results.filter((r) => r.technical_error).length;
const initialInvalid = results.filter((r) => r.initial_json_invalid).length;
const retries = results.filter((r) => r.retry_used).length;
const corrected = results.filter((r) => r.retry_used && r.retry_valid).length;
const retryInvalid = results.filter((r) => r.retry_json_invalid).length;
const fallbacks = results.filter((r) => r.fallback_used).length;
const http429Errors = results.filter((r) => r.http_429_error).length;
const http503Errors = results.filter((r) => r.http_503_error).length;
const logicalCalls = results.reduce((sum, r) => sum + (r.logical_calls ?? (r.retry_used ? 2 : 1)), 0);
const logicalLimit = results.length * 2;
if (logicalCalls > logicalLimit) throw new Error(`Plafond d'appels dépassé: ${logicalCalls}/${logicalLimit}.`);
const durationSum = results.reduce((sum, r) => sum + r.duration_ms, 0);
const completed = !calibrationOnly && results.length === 30;
const checkpoint = {
  version: 1,
  dataset_id: 'seed-demo-v1',
  model: 'models/gemini-3.5-flash',
  results: calibrationOnly ? [] : results,
  groups,
};
return [{ json: {
  benchmark: calibrationOnly ? 'single_calibration' : 'resumable_30',
  group_messages: currentResults.length,
  total_messages: results.length,
  remaining_messages: calibrationOnly ? 30 : 30 - results.length,
  completed,
  initial_valid: initialValid,
  initial_invalid: initialInvalid,
  retries_used: retries,
  corrections_succeeded: corrected,
  json_invalid_after_retry: retryInvalid,
  fallbacks_used: fallbacks,
  technical_errors: technicalErrors,
  http_429_errors: http429Errors,
  http_503_errors: http503Errors,
  initial_success_percentage: completed ? Number(((initialValid / 30) * 100).toFixed(2)) : null,
  logical_model_calls: logicalCalls,
  logical_call_limit: logicalLimit,
  transport_attempt_limit: results.length * 4,
  total_duration_ms: calibrationOnly ? groupDuration : groups.reduce((sum, group) => sum + group.duration_ms, 0),
  average_classification_duration_ms: Number((durationSum / results.length).toFixed(2)),
  results,
  checkpoint,
} }];

const report = $json;
const columns = ['fixture_id','first_attempt_valid','initial_json_invalid','retry_used','retry_valid','retry_json_invalid','fallback_used','first_attempt_technical_error','technical_error','http_429_error','http_503_error','error_code','duration_ms'];
const escape = (value) => {
  const text = value === null || value === undefined ? '' : String(value);
  return /[";,\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
};
const csv = [columns.join(';'), ...report.results.map((row) => columns.map((column) => escape(row[column])).join(';'))].join('\n');
const suffix = report.benchmark === 'single_calibration' ? 'calibration' : String(report.total_messages).padStart(2, '0');
return [{
  json: report,
  binary: {
    checkpoint: {
      data: Buffer.from(JSON.stringify(report.checkpoint, null, 2), 'utf8').toString('base64'),
      mimeType: 'application/json',
      fileName: `gemini-benchmark-checkpoint-${suffix}.json`,
    },
    results: {
      data: Buffer.from(csv, 'utf8').toString('base64'),
      mimeType: 'text/csv',
      fileName: `gemini-classification-benchmark-${suffix}.csv`,
    },
  },
}];
